/* ==========================================================================
   Vernier — design system
   A precision instrument: printed serif legends, ruled plates, graticule paper.
   Words are set in a system serif; figures only are set in a numeric face.
   Mode is a colour channel: cyan reads scientific, amber reads graph.
   ========================================================================== */

:root {
  /* --- base palette ------------------------------------------------------ */
  --ink: #0a0f0f;          /* page ground            */
  --panel: #0f1615;        /* plate                  */
  --panel-raised: #131c1b; /* key face, inset readout*/
  --bone: #f0eadd;         /* primary text           */
  --bone-dim: rgba(240, 234, 221, 0.62);
  --bone-faint: rgba(240, 234, 221, 0.38);
  --line: rgba(240, 234, 221, 0.13);
  --line-strong: rgba(240, 234, 221, 0.26);

  /* --- mode accents ------------------------------------------------------ */
  --cyan: #4fd1d9;
  --amber: #f2b457;
  --accent: var(--cyan);
  --accent-soft: rgba(79, 209, 217, 0.14);
  --accent-line: rgba(79, 209, 217, 0.34);
  --grid-line: rgba(79, 209, 217, 0.055);
  --grid-size: 36px;
  --grid-major: 180px;

  /* --- type -------------------------------------------------------------- */
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua",
           "URW Palladio L", Georgia, "Times New Roman", serif;
  --figures: ui-monospace, "SF Mono", SFMono-Regular, "Cascadia Mono",
             "DejaVu Sans Mono", Menlo, Consolas, "Liberation Mono", monospace;

  /* --- rhythm ------------------------------------------------------------ */
  --radius: 4px;
  --radius-sm: 2px;
  --gap: clamp(0.9rem, 1.8vw, 1.5rem);
  --pad: clamp(0.85rem, 1.6vw, 1.25rem);
  --shell: 1240px;

  --ease: cubic-bezier(0.2, 0.7, 0.25, 1);
}

body[data-mode="graph"] {
  --accent: var(--amber);
  --accent-soft: rgba(242, 180, 87, 0.14);
  --accent-line: rgba(242, 180, 87, 0.34);
  --grid-line: rgba(242, 180, 87, 0.06);
  --grid-size: 24px;
  --grid-major: 120px;
}

/* --------------------------------------------------------------------------
   Reset-ish
   -------------------------------------------------------------------------- */
*,
*::before,
*::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  min-height: 100vh;
  padding: clamp(1rem, 3vw, 2.5rem) clamp(0.85rem, 3vw, 2.5rem) 1.5rem;
  max-width: var(--shell);
  margin-inline: auto;
  background: var(--ink);
  color: var(--bone);
  font-family: var(--serif);
  font-size: 1rem;
  line-height: 1.55;
  font-kerning: normal;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}

h1, h2, p, ol, ul, figure { margin: 0; }

/* Graticule paper. The pitch and tint of the ruling is the ambient signal of
   which mode you are in: a wide cyan grid, or a tighter amber one. */
.graticule {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    repeating-linear-gradient(to right, var(--grid-line) 0 1px, transparent 1px var(--grid-size)),
    repeating-linear-gradient(to bottom, var(--grid-line) 0 1px, transparent 1px var(--grid-size)),
    repeating-linear-gradient(to right, var(--grid-line) 0 1px, transparent 1px var(--grid-major)),
    repeating-linear-gradient(to bottom, var(--grid-line) 0 1px, transparent 1px var(--grid-major));
  background-position: center top;
  -webkit-mask-image: linear-gradient(to bottom, #000 0%, rgba(0, 0, 0, 0.35) 62%, transparent 100%);
  mask-image: linear-gradient(to bottom, #000 0%, rgba(0, 0, 0, 0.35) 62%, transparent 100%);
  transition: opacity 0.3s var(--ease);
}

/* --------------------------------------------------------------------------
   Masthead
   -------------------------------------------------------------------------- */
.masthead {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem var(--gap);
  padding-bottom: var(--gap);
  border-bottom: 1px solid var(--line-strong);
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  min-width: 0;
}

.brand__mark {
  width: 30px;
  height: 30px;
  flex: none;
  color: var(--accent);
  transition: color 0.28s var(--ease);
}

.brand__name {
  font-size: clamp(1.35rem, 2.4vw, 1.65rem);
  font-weight: 400;
  letter-spacing: 0.01em;
  line-height: 1.1;
  font-variant-caps: normal;
}

.brand__sub {
  color: var(--bone-dim);
  font-size: 0.82rem;
  font-style: italic;
  line-height: 1.3;
  margin-top: 0.12rem;
}

/* --- Mode switch: a two-position instrument switch, not a pill ----------- */
.modes {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  padding: 3px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--panel);
  isolation: isolate;
}

.modes__thumb {
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 3px;
  width: calc(50% - 3px);
  z-index: 0;
  border-radius: var(--radius-sm);
  background: var(--accent);
  box-shadow: inset 0 0 0 1px rgba(10, 15, 15, 0.25);
  transition: transform 0.28s var(--ease), background-color 0.28s var(--ease);
}

body[data-mode="graph"] .modes__thumb { transform: translateX(100%); }

.modes__tab {
  position: relative;
  z-index: 1;
  appearance: none;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--bone-dim);
  font-family: var(--serif);
  font-size: 0.95rem;
  line-height: 1;
  padding: 0.62rem 1.15rem;
  cursor: pointer;
  transition: color 0.18s var(--ease);
}

.modes__tab[aria-selected="true"] {
  color: var(--ink);
  font-weight: 600;
}

.modes__tab:not([aria-selected="true"]):hover { color: var(--bone); }

/* --------------------------------------------------------------------------
   Workspace grid
   -------------------------------------------------------------------------- */
.workspace {
  display: grid;
  gap: var(--gap);
  grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
  grid-template-areas: "calc history";
  align-items: start;
}

body[data-mode="graph"] .workspace {
  grid-template-areas:
    "calc history"
    "graph graph";
}

.workspace:focus-visible { outline: none; }

.calc    { grid-area: calc; }
.history { grid-area: history; }
.graph   { grid-area: graph; }

/* --------------------------------------------------------------------------
   Panel primitive
   -------------------------------------------------------------------------- */
.panel {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--pad);
  padding: var(--pad);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  min-width: 0;
}

/* the leading accent tick that carries the mode colour into every plate */
.panel::before {
  content: "";
  position: absolute;
  top: -1px;
  left: var(--pad);
  width: 34px;
  height: 2px;
  background: var(--accent);
  transition: background-color 0.28s var(--ease);
}

.panel__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  min-width: 0;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid var(--line);
}

.panel__title {
  font-size: 1rem;
  font-weight: 400;
  font-variant-caps: small-caps;
  letter-spacing: 0.055em;
  color: var(--bone);
  line-height: 1.2;
  white-space: nowrap;
}

/* --------------------------------------------------------------------------
   Readout — the instrument display
   -------------------------------------------------------------------------- */
.readout {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  padding: 0.85rem 0.95rem 0.8rem;
  background: var(--panel-raised);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.readout::after {              /* carriage rule, drawn once on load */
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: var(--accent);
  transform-origin: left center;
  transition: background-color 0.28s var(--ease);
  animation: carriage 620ms var(--ease) both;
}

@keyframes carriage {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}

.readout__expr {
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  font-size: 0.85rem;
  color: var(--bone-faint);
  text-align: right;
  white-space: nowrap;
  overflow-x: auto;
  scrollbar-width: none;
  min-height: 1.2em;
}

.readout__expr::-webkit-scrollbar { display: none; }

.readout__value {
  display: block;
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "zero" 0;
  font-size: clamp(2.1rem, 6.6vw, 3.9rem);
  font-weight: 400;
  line-height: 1.05;
  letter-spacing: -0.015em;
  text-align: right;
  color: var(--bone);
  white-space: nowrap;
  overflow-x: auto;
  scrollbar-width: none;
}

.readout__value::-webkit-scrollbar { display: none; }

.readout__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  padding-top: 0.3rem;
}

/* --------------------------------------------------------------------------
   Chips and small utilities
   -------------------------------------------------------------------------- */
.chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.14rem 0.5rem;
  border: 1px solid var(--accent-line);
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  color: var(--accent);
  font-family: var(--serif);
  font-size: 0.76rem;
  letter-spacing: 0.02em;
  line-height: 1.5;
  white-space: nowrap;
  transition: color 0.28s var(--ease), border-color 0.28s var(--ease),
              background-color 0.28s var(--ease);
}

.chip--quiet {
  border-color: var(--line);
  background: transparent;
  color: var(--bone-dim);
}

.link {
  appearance: none;
  border: 0;
  background: none;
  padding: 0.1rem 0.15rem;
  color: var(--bone-dim);
  font-family: var(--serif);
  font-size: 0.8rem;
  font-style: italic;
  cursor: pointer;
  border-bottom: 1px solid transparent;
  transition: color 0.15s var(--ease), border-color 0.15s var(--ease);
}

.link:hover {
  color: var(--bone);
  border-bottom-color: var(--line-strong);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}

.row {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-width: 0;
}

.row--tight { gap: 0.35rem; flex-wrap: wrap; justify-content: flex-end; }

/* --------------------------------------------------------------------------
   Keypad
   -------------------------------------------------------------------------- */
.keypad {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.keypad__fn,
.keypad__pad {
  display: grid;
  gap: 0.4rem;
}

.keypad__fn  { grid-template-columns: repeat(6, minmax(0, 1fr)); }
.keypad__pad { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0.45rem; }

.key {
  appearance: none;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.4rem 0.25rem;
  font-family: var(--serif);
  font-size: 1rem;
  line-height: 1;
  color: var(--bone);
  background: var(--panel-raised);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.13s var(--ease), border-color 0.13s var(--ease),
              color 0.13s var(--ease), transform 0.07s var(--ease);
}

.key:hover {
  background: #17211f;
  border-color: var(--line-strong);
}

.key:active { transform: translateY(1px); }

.key sup {
  font-size: 0.62em;
  line-height: 0;
  vertical-align: super;
}

.key--fn {
  min-height: 2.15rem;
  font-size: 0.88rem;
  color: var(--bone-dim);
  background: transparent;
}

.key--fn:hover { color: var(--bone); }

.key--fn[aria-pressed="true"],
.key--fn.is-active {
  color: var(--accent);
  border-color: var(--accent-line);
  background: var(--accent-soft);
}

.key--digit {
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  font-size: 1.1rem;
  min-height: 2.9rem;
}

.key--op {
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  font-size: 1.1rem;
  color: var(--accent);
  transition: background-color 0.13s var(--ease), border-color 0.13s var(--ease),
              color 0.13s var(--ease), transform 0.07s var(--ease);
}

.key--op:hover {
  background: var(--accent-soft);
  border-color: var(--accent-line);
}

.key--util {
  font-size: 0.9rem;
  color: var(--bone-dim);
}

.key--equals {
  grid-column: span 2;
  font-family: var(--figures);
  font-size: 1.15rem;
  min-height: 2.9rem;
  color: var(--ink);
  background: var(--accent);
  border-color: var(--accent);
  transition: filter 0.13s var(--ease), background-color 0.28s var(--ease),
              border-color 0.28s var(--ease), transform 0.07s var(--ease);
}

.key--equals:hover { filter: brightness(1.1); background: var(--accent); }

/* --------------------------------------------------------------------------
   History — a ledger, ruled rather than carded
   -------------------------------------------------------------------------- */
.history__list {
  list-style: none;
  padding: 0;
  margin: -0.35rem 0 0;
  max-height: 26rem;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--line-strong) transparent;
}

.history__item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 0.75rem;
  padding: 0.55rem 0;
  border-top: 1px solid var(--line);
}

.history__item:first-child { border-top: 0; }

.history__expr {
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  font-size: 0.8rem;
  color: var(--bone-dim);
  overflow-wrap: anywhere;
}

.history__result {
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  font-size: 0.98rem;
  color: var(--bone);
  white-space: nowrap;
}

.history__empty {
  padding: 0.6rem 0 0.3rem;
  color: var(--bone-faint);
  font-size: 0.85rem;
  font-style: italic;
  line-height: 1.5;
  max-width: 30ch;
}

/* --------------------------------------------------------------------------
   Graph
   -------------------------------------------------------------------------- */
.graph { display: none; }

body[data-mode="graph"] .graph { display: flex; }

.graph__body {
  display: grid;
  gap: var(--gap);
  grid-template-columns: minmax(0, 1.75fr) minmax(0, 1fr);
  align-items: start;
}

.plot {
  position: relative;
  aspect-ratio: 16 / 10;
  min-height: 200px;
  background:
    repeating-linear-gradient(to right, var(--grid-line) 0 1px, transparent 1px var(--grid-size)),
    repeating-linear-gradient(to bottom, var(--grid-line) 0 1px, transparent 1px var(--grid-size)),
    #0b1211;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

#graph-canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

.plot__empty {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  padding: 1rem;
  text-align: center;
  color: var(--bone-faint);
  font-size: 0.9rem;
  line-height: 1.6;
  max-width: 32ch;
  margin-inline: auto;
}

.plot__eg {
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  color: var(--bone-dim);
}

.graph__form {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  min-width: 0;
}

.graph__field {
  padding: 0.4rem 0.45rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--panel-raised);
}

.graph__field:focus-within { border-color: var(--accent-line); }

.swatch {
  flex: none;
  width: 6px;
  height: 1.1rem;
  border-radius: 1px;
  background: var(--accent);
  transition: background-color 0.28s var(--ease);
}

.swatch--b { background: var(--bone-faint); }

.input {
  flex: 1 1 auto;
  min-width: 0;
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--bone);
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  font-size: 0.95rem;
  padding: 0.2rem 0.1rem;
}

.input::placeholder {
  color: var(--bone-faint);
  font-style: italic;
  font-family: var(--serif);
}

.input:focus { outline: none; }

.btn {
  appearance: none;
  flex: none;
  padding: 0.34rem 0.8rem;
  border: 1px solid var(--accent-line);
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  color: var(--accent);
  font-family: var(--serif);
  font-size: 0.82rem;
  cursor: pointer;
  transition: background-color 0.15s var(--ease), border-color 0.15s var(--ease),
              color 0.15s var(--ease);
}

.btn:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--ink);
}

/* --------------------------------------------------------------------------
   Colophon
   -------------------------------------------------------------------------- */
.colophon {
  margin-top: auto;
  padding-top: 0.9rem;
  border-top: 1px solid var(--line);
}

.colophon__line {
  color: var(--bone-faint);
  font-size: 0.78rem;
  font-style: italic;
}

/* --------------------------------------------------------------------------
   Focus — visible everywhere, tuned per surface
   -------------------------------------------------------------------------- */
:where(button, input, [tabindex]):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.modes__tab[aria-selected="true"]:focus-visible {
  outline-color: var(--bone);
}

.key--equals:focus-visible {
  outline-color: var(--bone);
  outline-offset: 2px;
}

/* --------------------------------------------------------------------------
   Responsive — single column from 860px, holds down to 360px
   -------------------------------------------------------------------------- */
@media (max-width: 860px) {
  .workspace,
  body[data-mode="graph"] .workspace {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: "calc" "history";
  }

  body[data-mode="graph"] .workspace {
    grid-template-areas: "calc" "graph" "history";
  }

  .graph__body { grid-template-columns: minmax(0, 1fr); }

  .history__list { max-height: 18rem; }
}

@media (max-width: 560px) {
  .masthead {
    flex-direction: column;
    align-items: stretch;
  }

  .modes { width: 100%; }

  .modes__tab { padding: 0.62rem 0.5rem; text-align: center; }

  .brand__sub { font-size: 0.78rem; }

  .panel__title { font-size: 0.95rem; }
}

@media (max-width: 400px) {
  :root { --pad: 0.7rem; --gap: 0.7rem; }

  .keypad__fn { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0.32rem; }
  .keypad__pad { gap: 0.32rem; }

  .key { min-height: 2.5rem; font-size: 0.94rem; }
  .key--digit,
  .key--op { font-size: 1.02rem; min-height: 2.65rem; }
  .key--fn { min-height: 2rem; font-size: 0.82rem; }
  .key--equals { min-height: 2.65rem; }

  .readout__value { font-size: 2rem; }
  .readout__expr { font-size: 0.78rem; }

  .plot { aspect-ratio: 4 / 3; }
}

/* --------------------------------------------------------------------------
   Reduced motion — no thumb slide, no key nudge, no carriage draw
   -------------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }

  .readout::after { animation: none; transform: none; }
  .key:active { transform: none; }
}

