from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(s):
        super().__init__(); s.stack=[]; s.void={'meta','link','br','img','input','hr','source','path','rect'}
    def handle_starttag(s,t,a):
        if t not in s.void: s.stack.append((t,s.getpos()))
    def handle_endtag(s,t):
        if t in s.void: return
        if not s.stack or s.stack[-1][0]!=t: print('MISMATCH end',t,'at',s.getpos(),'open:',s.stack[-3:]); s.stack and s.stack.pop()
        else: s.stack.pop()
p=P(); p.feed(open('preview.html').read()); print('unclosed:',p.stack)
"; python3 -c "import playwright, sys; print('playwright ok')" 2>&1 | tail -1

