/*!
 * Vernier — static/js/scientific.js
 * ---------------------------------------------------------------------------
 * The scientific panel: keypad, live expression line, live preview readout,
 * a scrollable history ledger, an angle-unit toggle, and a small results
 * sparkline + status chip that together show the computation state.
 *
 * All maths goes through window.CalcEngine (static/js/engine.js). This file
 * contains no parsing, no evaluation and no number formatting of its own — if
 * the engine is missing the keypad stays inert instead of drifting out of sync.
 *
 * Shared app state
 *   Angle mode and `ans` are app state, not panel state, so graph mode can
 *   honour them. They live in the `state` object published as
 *   window.Vernier.state, with:
 *       Vernier.getAngleMode() / Vernier.setAngleMode("DEG"|"RAD")
 *       Vernier.getScope()   -> { ans: <last committed value> }
 *       Vernier.getPrecision()
 *       Vernier.on("anglechange"|"historychange", fn) -> unsubscribe
 *   setAngleMode() also mirrors the mode into CalcEngine.setAngleMode(), so a
 *   graph sampler that passes no options still uses the same unit.
 *
 * Keyboard
 *   0-9 . + - * / ^ % ( ) ! and letters type into the expression, Enter / =
 *   commits, Backspace deletes, Escape / Delete clears. Keys are ignored while
 *   an input has focus or while the app is in graph mode, and never steal the
 *   native Enter/Space activation of a focused button.
 * ---------------------------------------------------------------------------
 */
(function (global) {
  "use strict";

  var doc = global.document;
  var Engine = global.CalcEngine;

  if (!doc || !Engine) {
    if (global.console && global.console.warn) {
      global.console.warn(
        "Vernier: static/js/scientific.js needs window.CalcEngine from " +
          "static/js/engine.js. Keypad left inert."
      );
    }
    return;
  }

  /* ------------------------------------------------------------------ *
   * Constants
   * ------------------------------------------------------------------ */

  var MAX_HISTORY = 50;
  var SPARK_POINTS = 24;
  var SPARK_W = 120;
  var SPARK_H = 30;
  var SPARK_PAD = 3;

  var STATUS_TEXT = {
    idle: "Ready",
    preview: "Preview",
    done: "Result",
    error: "Check input"
  };

  var FUNCTIONS = {
    sin: "sin",
    cos: "cos",
    tan: "tan",
    ln: "ln",
    log: "log",
    sqrt: "sqrt"
  };

  /* ------------------------------------------------------------------ *
   * Shared app state
   * ------------------------------------------------------------------ */

  var state = {
    expression: "",
    angleMode: Engine.getAngleMode ? Engine.getAngleMode() === "RAD" ? "RAD" : "DEG" : "DEG",
    precision: (Engine.DEFAULTS && Engine.DEFAULTS.precision) || 12,
    ans: 0,
    display: "0",
    preview: null,
    history: [],
    phase: "idle", // idle | preview | done | error
    message: "",
    soft: false, // error is just an unfinished expression
    fresh: true // expression came from a commit; next digit starts over
  };

  var listeners = {};

  var el = {};

  /* ------------------------------------------------------------------ *
   * Small helpers
   * ------------------------------------------------------------------ */

  function byId(id) {
    return doc.getElementById(id);
  }

  function closest(node, selector) {
    var target = node;
    while (target && target !== doc) {
      if (target.nodeType === 1) {
        if (target.matches && target.matches(selector)) return target;
        if (target.msMatchesSelector && target.msMatchesSelector(selector)) return target;
        if (target.webkitMatchesSelector && target.webkitMatchesSelector(selector)) return target;
      }
      target = target.parentNode;
    }
    return null;
  }

  function toggleClass(node, name, on) {
    if (!node) return;
    if (!node.classList) return;
    if (on) node.classList.add(name);
    else node.classList.remove(name);
  }

  function round(n) {
    return Math.round(n * 10) / 10;
  }

  /** ASCII maths in state, typographic maths on screen. */
  function displayExpression(text) {
    return String(text)
      .replace(/\*/g, "\u00d7")
      .replace(/\//g, "\u00f7")
      .replace(/-/g, "\u2212");
  }

  function emit(name, payload) {
    var list = listeners[name];
    if (!list) return;
    for (var i = 0; i < list.length; i++) {
      try {
        list[i](payload, state);
      } catch (error) {
        if (global.console && global.console.error) global.console.error(error);
      }
    }
  }

  function announce(message) {
    if (!el.announcer) return;
    // Clearing first makes a repeated, identical message speak again.
    el.announcer.textContent = "";
    global.setTimeout(function () {
      if (el.announcer) el.announcer.textContent = message;
    }, 40);
  }

  function messageFor(error) {
    if (error && typeof error.message === "string" && error.message) return error.message;
    return "That expression cannot be calculated.";
  }

  function isIncomplete(error) {
    var code = error && error.code;
    return code === "empty" || code === "syntax" || code === "unbalanced";
  }

  /* ------------------------------------------------------------------ *
   * Expression editing primitives
   * ------------------------------------------------------------------ */

  function clearAll() {
    state.expression = "";
    state.fresh = true;
    state.phase = "idle";
    state.preview = null;
    state.message = "";
    state.soft = false;
  }

  function trailingNumber(expr) {
    var match = /(\d*\.?\d*)$/.exec(expr);
    if (!match) return null;
    return { text: match[1], start: expr.length - match[1].length };
  }

  function endsWithOperand(expr) {
    if (!expr) return false;
    if (/[0-9)!%]$/.test(expr)) return true;
    return /(?:pi|tau|ans|e)$/.test(expr);
  }

  function appendDigit(digit) {
    if (state.fresh) {
      state.expression = "";
      state.fresh = false;
    }
    var tail = trailingNumber(state.expression);
    if (tail && tail.text === "0") {
      state.expression = state.expression.slice(0, tail.start) + digit;
    } else {
      state.expression += digit;
    }
  }

  function appendDecimal() {
    if (state.fresh) {
      state.expression = "";
      state.fresh = false;
    }
    var tail = trailingNumber(state.expression);
    if (tail && tail.text.indexOf(".") >= 0) return;
    if (!tail || tail.text === "") state.expression += "0.";
    else state.expression += ".";
  }

  function appendOperator(operator) {
    if (state.fresh) {
      state.expression = "ans";
      state.fresh = false;
    }
    var expr = state.expression;
    if (!expr) {
      if (operator === "-") state.expression = "-";
      return;
    }
    var last = expr.slice(-1);
    if (/[+\-*/^]/.test(last)) {
      var previous = expr.slice(0, -1);
      var unaryContext = previous === "" || /[+\-*/^(]$/.test(previous);
      // a trailing minus may be a unary sign: "(-" , "^-" , "*-"
      state.expression = unaryContext ? expr + operator : previous + operator;
      return;
    }
    state.expression = expr + operator;
  }

  function appendFunction(name) {
    if (state.fresh) {
      state.expression = "";
      state.fresh = false;
    }
    state.expression += name + "(";
  }

  function appendToken(token) {
    if (state.fresh) {
      state.expression = "";
      state.fresh = false;
    }
    state.expression += token;
  }

  /** x², 1/x, n!, % — all need an operand in front of them. */
  function appendSuffix(suffix) {
    if (state.fresh) {
      state.expression = "ans";
      state.fresh = false;
    }
    if (!state.expression) state.expression = "ans";
    if (!endsWithOperand(state.expression)) return;
    state.expression += suffix;
  }

  function closeParen() {
    var expr = state.expression;
    if (!expr) return;
    var opens = (expr.match(/\(/g) || []).length;
    var closes = (expr.match(/\)/g) || []).length;
    if (opens <= closes) return;
    if (!endsWithOperand(expr)) return;
    state.expression = expr + ")";
    state.fresh = false;
  }

  function toggleSign() {
    var expr = state.expression;
    if (state.fresh) {
      expr = "ans";
      state.fresh = false;
    }
    var number = /(^|[+\-*/^(])(-?)((?:\d+\.?\d*|\.\d+))$/.exec(expr);
    if (number) {
      var start = number.index + number[1].length;
      expr = expr.slice(0, start) + (number[2] === "-" ? number[3] : "-" + number[3]);
    } else if (/\)$/.test(expr)) {
      expr = "-(" + expr + ")";
    } else if (/(^|[+\-*/^(])-$/.test(expr)) {
      expr = expr.slice(0, -1);
    } else if (expr && /[+\-*/^(]$/.test(expr)) {
      expr += "-";
    } else if (expr) {
      expr = "-" + expr;
    } else {
      expr = "-";
    }
    state.expression = expr;
  }

  function removeLast() {
    var expr = state.expression;
    if (!expr) return;
    var call = /(asin|acos|atan|sinh|cosh|tanh|sin|cos|tan|log2|ln|log|sqrt|cbrt|abs|exp|round|floor|ceil)\($/.exec(
      expr
    );
    if (call) expr = expr.slice(0, call.index);
    else if (/\^\(-1\)$/.test(expr)) expr = expr.slice(0, -6);
    else if (/\^-1$/.test(expr)) expr = expr.slice(0, -3);
    else expr = expr.slice(0, -1);
    state.expression = expr;
    state.fresh = false;
  }

  /* ------------------------------------------------------------------ *
   * Evaluation (preview + commit)
   * ------------------------------------------------------------------ */

  function evaluateCurrent() {
    var value = Engine.evaluate(state.expression, {
      angleMode: state.angleMode,
      scope: { ans: state.ans },
      strict: true
    });
    if (typeof value !== "number" || value !== value || !isFinite(value)) {
      throw new Engine.CalcError(
        "That works out to a value this calculator cannot show.",
        "overflow",
        0
      );
    }
    return value;
  }

  /** Recompute the live preview from the current expression. */
  function update() {
    if (!state.expression.replace(/\s+/g, "")) {
      state.phase = "idle";
      state.message = "";
      state.soft = false;
      state.preview = null;
      state.display = "0";
      render();
      return;
    }
    try {
      var value = evaluateCurrent();
      state.preview = value;
      state.display = Engine.format(value, { precision: state.precision });
      state.phase = "preview";
      state.message = "";
      state.soft = false;
    } catch (error) {
      state.preview = null;
      state.phase = "error";
      state.soft = isIncomplete(error);
      state.message = messageFor(error);
    }
    render();
  }

  function pushHistory(expression, result, value) {
    state.history.unshift({
      expression: expression,
      result: result,
      value: value,
      angleMode: state.angleMode
    });
    while (state.history.length > MAX_HISTORY) state.history.pop();
    renderHistory();
    renderSpark();
    emit("historychange", state.history);
  }

  /** Equals: commit the expression, keep it, and read it out. */
  function commit() {
    if (!state.expression.replace(/\s+/g, "")) {
      announce("There is nothing to calculate yet.");
      return;
    }
    try {
      var value = evaluateCurrent();
      state.ans = value;
      state.preview = value;
      state.display = Engine.format(value, { precision: state.precision });
      state.phase = "done";
      state.message = "";
      state.soft = false;
      state.fresh = true;
      pushHistory(state.expression, state.display, value);
      render();
      announce(displayExpression(state.expression) + " equals " + state.display + ".");
    } catch (error) {
      state.preview = null;
      state.phase = "error";
      state.soft = isIncomplete(error);
      state.message = messageFor(error);
      render();
      announce(
        "Error. " + (state.soft ? "The expression is not finished yet." : state.message)
      );
    }
  }

  /* ------------------------------------------------------------------ *
   * Rendering
   * ------------------------------------------------------------------ */

  function render() {
    if (el.expression) {
      el.expression.textContent = displayExpression(state.expression) || "\u00a0";
    }
    if (el.value) {
      el.value.textContent = state.display;
      toggleClass(el.value, "is-preview", state.phase === "preview");
      toggleClass(el.value, "is-committed", state.phase === "done");
      toggleClass(el.value, "is-error", state.phase === "error");
    }
    renderStatus();
    renderNote();
    renderAngle();
    renderSpark();
  }

  function renderStatus() {
    if (!el.status) return;
    el.status.setAttribute("data-state", state.phase);
    if (state.phase === "error" && state.soft) {
      el.status.setAttribute("data-soft", "true");
      el.status.textContent = "Incomplete";
    } else {
      el.status.removeAttribute("data-soft");
      el.status.textContent = STATUS_TEXT[state.phase] || "Ready";
    }
    el.status.setAttribute("title", state.message || "");
  }

  function renderNote() {
    if (!el.note) return;
    var text = "";
    var tone = "quiet";
    if (state.phase === "error") {
      if (state.soft) {
        text = "Keep going \u2014 the expression is not finished yet.";
      } else {
        text = state.message;
        tone = "error";
      }
    } else if (state.phase === "idle") {
      text = "Type an expression, or use the keypad.";
    } else if (state.phase === "preview") {
      text = "Live preview. Press = to keep this result.";
    } else if (state.phase === "done") {
      text = "Result kept in history. Every entry restores its expression.";
    }
    el.note.setAttribute("data-tone", tone);
    el.note.textContent = text;
    if (text) el.note.removeAttribute("hidden");
    else el.note.setAttribute("hidden", "hidden");
  }

  function renderAngle() {
    if (el.angle) {
      el.angle.textContent = state.angleMode;
      el.angle.setAttribute("data-angle", state.angleMode.toLowerCase());
      el.angle.setAttribute(
        "aria-label",
        state.angleMode === "DEG"
          ? "Angle unit: degrees. Activate to switch to radians."
          : "Angle unit: radians. Activate to switch to degrees."
      );
    }
    if (el.precision) el.precision.textContent = state.precision + " digits";
    doc.body.setAttribute("data-angle", state.angleMode.toLowerCase());
  }

  /* ------------------------------------------------------------------ *
   * Sparkline — recent results, log-squashed so 0.5 and 10⁶ share a frame
   * ------------------------------------------------------------------ */

  function sparkSeries() {
    var values = [];
    var i;
    for (i = state.history.length - 1; i >= 0 && values.length < SPARK_POINTS - 1; i--) {
      values.push(state.history[i].value);
    }
    values.reverse();
    if ((state.phase === "preview" || state.phase === "done") && typeof state.preview === "number") {
      values.push(state.preview);
    }
    return values;
  }

  function renderSpark() {
    if (!el.spark || !el.sparkLine) return;
    var raw = sparkSeries();
    var scaled = [];
    var i;
    for (i = 0; i < raw.length; i++) {
      if (typeof raw[i] === "number" && isFinite(raw[i])) {
        scaled.push((Math.log(1 + Math.abs(raw[i])) / Math.LN10) * (raw[i] < 0 ? -1 : 1));
      }
    }

    el.spark.setAttribute("data-state", state.phase === "error" ? "error" : scaled.length ? "preview" : "idle");

    if (!scaled.length) {
      el.sparkLine.setAttribute("points", "");
      if (el.sparkDot) el.sparkDot.setAttribute("r", "0");
      return;
    }

    var min = scaled[0];
    var max = scaled[0];
    for (i = 1; i < scaled.length; i++) {
      if (scaled[i] < min) min = scaled[i];
      if (scaled[i] > max) max = scaled[i];
    }
    var span = max - min;
    var flat = !(span > 1e-9);

    var points = [];
    for (i = 0; i < scaled.length; i++) {
      var x =
        scaled.length === 1
          ? SPARK_W - SPARK_PAD
          : SPARK_PAD + ((SPARK_W - 2 * SPARK_PAD) * i) / (scaled.length - 1);
      var y = flat
        ? SPARK_H / 2
        : SPARK_H - SPARK_PAD - ((scaled[i] - min) / span) * (SPARK_H - 2 * SPARK_PAD);
      points.push(round(x) + "," + round(y));
    }

    el.sparkLine.setAttribute("points", points.join(" "));
    if (el.sparkDot) {
      var last = points[points.length - 1].split(",");
      el.sparkDot.setAttribute("cx", last[0]);
      el.sparkDot.setAttribute("cy", last[1]);
      el.sparkDot.setAttribute("r", "2.2");
    }
  }

  /* ------------------------------------------------------------------ *
   * History ledger
   * ------------------------------------------------------------------ */

  function historyNode(entry, index) {
    var item = doc.createElement("li");
    item.className = "history__row";

    var button = doc.createElement("button");
    button.type = "button";
    button.className = "history__entry";
    button.setAttribute("data-index", String(index));
    button.setAttribute("title", "Restore " + displayExpression(entry.expression));
    button.setAttribute(
      "aria-label",
      "Restore " + displayExpression(entry.expression) + ", which equals " + entry.result
    );

    var expression = doc.createElement("span");
    expression.className = "history__expr";
    expression.textContent = displayExpression(entry.expression);

    var result = doc.createElement("span");
    result.className = "history__result";
    result.textContent = "= " + entry.result;

    button.appendChild(expression);
    button.appendChild(result);
    item.appendChild(button);
    return item;
  }

  function renderHistory() {
    if (!el.historyList) return;
    var list = el.historyList;
    var children = [].slice.call(list.childNodes);
    var i;
    for (i = 0; i < children.length; i++) {
      var node = children[i];
      if (node.nodeType !== 1) continue;
      if (node.id === "history-empty") continue;
      list.removeChild(node);
    }
    if (el.historyEmpty) {
      if (state.history.length) el.historyEmpty.setAttribute("hidden", "hidden");
      else el.historyEmpty.removeAttribute("hidden");
    }
    if (!state.history.length) return;
    var fragment = doc.createDocumentFragment();
    for (i = 0; i < state.history.length; i++) {
      fragment.appendChild(historyNode(state.history[i], i));
    }
    list.insertBefore(fragment, list.firstChild);
  }

  function restoreHistory(index) {
    var entry = state.history[index];
    if (!entry) return;
    state.expression = entry.expression;
    state.fresh = false;
    update();
    announce("Restored " + displayExpression(entry.expression) + " to the expression line.");
  }

  function clearHistory() {
    if (!state.history.length) return;
    state.history = [];
    renderHistory();
    renderSpark();
    emit("historychange", state.history);
    announce("History cleared.");
  }

  /* ------------------------------------------------------------------ *
   * Angle mode — shared app state
   * ------------------------------------------------------------------ */

  function setAngleMode(mode) {
    var next = String(mode == null ? "" : mode).toUpperCase() === "RAD" ? "RAD" : "DEG";
    state.angleMode = next;
    if (Engine.setAngleMode) Engine.setAngleMode(next);
    renderAngle();
    update();
    announce("Angle unit set to " + (next === "DEG" ? "degrees." : "radians."));
    emit("anglechange", next);
    return next;
  }

  function getAngleMode() {
    return state.angleMode;
  }

  /* ------------------------------------------------------------------ *
   * Keypad + keyboard
   * ------------------------------------------------------------------ */

  function press(key) {
    switch (key) {
      case "clear":
        clearAll();
        break;
      case "backspace":
        removeLast();
        break;
      case "equals":
        commit();
        return;
      case "open":
        if (state.fresh) {
          state.expression = "";
          state.fresh = false;
        }
        state.expression += "(";
        break;
      case "close":
        closeParen();
        break;
      case "decimal":
        appendDecimal();
        break;
      case "negate":
        toggleSign();
        break;
      case "square":
        appendSuffix("^2");
        break;
      case "power":
        appendOperator("^");
        break;
      case "reciprocal":
        appendSuffix("^-1");
        break;
      case "factorial":
        appendSuffix("!");
        break;
      case "percent":
        appendSuffix("%");
        break;
      case "pi":
        appendToken("pi");
        break;
      case "e":
        appendToken("e");
        break;
      case "ans":
        appendToken("ans");
        break;
      case "add":
        appendOperator("+");
        break;
      case "subtract":
        appendOperator("-");
        break;
      case "multiply":
        appendOperator("*");
        break;
      case "divide":
        appendOperator("/");
        break;
      case "0":
      case "1":
      case "2":
      case "3":
      case "4":
      case "5":
      case "6":
      case "7":
      case "8":
      case "9":
        appendDigit(key);
        break;
      default:
        if (Object.prototype.hasOwnProperty.call(FUNCTIONS, key)) {
          appendFunction(FUNCTIONS[key]);
        } else {
          return;
        }
    }
    update();
  }

  function insertChar(ch) {
    if (state.fresh) {
      state.expression = "";
      state.fresh = false;
    }
    state.expression += ch;
    update();
  }

  function bindKeypad() {
    el.keypad.addEventListener("click", function (event) {
      var button = closest(event.target, "button[data-key]");
      if (!button) return;
      press(button.getAttribute("data-key"));
    });
  }

  function bindKeyboard() {
    doc.addEventListener("keydown", function (event) {
      if (event.defaultPrevented || event.ctrlKey || event.metaKey || event.altKey) return;
      if (doc.body.getAttribute("data-mode") !== "scientific") return;

      var target = event.target;
      if (target && target.nodeType === 1) {
        if (/^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName) || target.isContentEditable) return;
        // let a focused button keep its native Enter / Space activation
        if (/^(BUTTON|A)$/.test(target.tagName) && (event.key === "Enter" || event.key === " ")) {
          return;
        }
      }

      var key = event.key;
      var handled = true;

      switch (key) {
        case "Enter":
        case "=":
          commit();
          break;
        case "Backspace":
          removeLast();
          update();
          break;
        case "Escape":
        case "Delete":
          clearAll();
          update();
          break;
        case ".":
        case ",":
          press("decimal");
          break;
        case "+":
          press("add");
          break;
        case "-":
          press("subtract");
          break;
        case "*":
          press("multiply");
          break;
        case "x":
        case "X":
          press("multiply");
          break;
        case "/":
          press("divide");
          break;
        case "^":
          press("power");
          break;
        case "%":
          press("percent");
          break;
        case "(":
          press("open");
          break;
        case ")":
          press("close");
          break;
        case "!":
          press("factorial");
          break;
        default:
          if (/^[0-9]$/.test(key)) press(key);
          else if (/^[a-z]$/i.test(key) && key.length === 1) insertChar(key.toLowerCase());
          else handled = false;
      }

      if (handled) event.preventDefault();
    });
  }

  function bindAngle() {
    if (!el.angle) return;
    el.angle.addEventListener("click", function () {
      setAngleMode(state.angleMode === "DEG" ? "RAD" : "DEG");
    });
  }

  function bindHistory() {
    if (el.historyList) {
      el.historyList.addEventListener("click", function (event) {
        var button = closest(event.target, "button[data-index]");
        if (!button) return;
        restoreHistory(parseInt(button.getAttribute("data-index"), 10));
      });
    }
    if (el.historyClear) el.historyClear.addEventListener("click", clearHistory);
  }

  /* ------------------------------------------------------------------ *
   * Public surface for the rest of the app
   * ------------------------------------------------------------------ */

  function publish() {
    var app = global.Vernier || (global.Vernier = {});
    app.state = state;
    app.getAngleMode = getAngleMode;
    app.setAngleMode = setAngleMode;
    app.getPrecision = function () {
      return state.precision;
    };
    app.getScope = function () {
      return { ans: state.ans };
    };
    app.on = function (name, handler) {
      if (typeof handler !== "function") return function () {};
      var list = listeners[name] || (listeners[name] = []);
      list.push(handler);
      return function () {
        var index = list.indexOf(handler);
        if (index >= 0) list.splice(index, 1);
      };
    };
  }

  /* ------------------------------------------------------------------ *
   * Boot
   * ------------------------------------------------------------------ */

  function init() {
    el.expression = byId("expression");
    el.value = byId("readout-value");
    el.note = byId("readout-note");
    el.status = byId("status-chip");
    el.angle = byId("angle-chip");
    el.precision = byId("precision-chip");
    el.spark = byId("spark");
    el.sparkLine = byId("spark-line");
    el.sparkDot = byId("spark-dot");
    el.announcer = byId("announcer");
    el.keypad = byId("keypad");
    el.historyList = byId("history-list");
    el.historyEmpty = byId("history-empty");
    el.historyClear = byId("history-clear");

    if (!el.keypad || !el.expression || !el.value) {
      if (global.console && global.console.warn) {
        global.console.warn("Vernier: scientific panel markup not found; nothing wired.");
      }
      return;
    }

    if (Engine.setAngleMode) Engine.setAngleMode(state.angleMode);

    bindKeypad();
    bindKeyboard();
    bindAngle();
    bindHistory();
    publish();

    // Seed the preview with one worked expression so the standalone page shows
    // the preview/commit cycle immediately. AC clears it.
    state.expression = "sin(30)*12";
    state.fresh = false;

    update();
    renderHistory();
  }

  if (doc.readyState === "loading") {
    doc.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})(typeof window !== "undefined" ? window : this);

