  color: #e5907f; /* error clay — deliberately not a mode accent */
}

.readout__note[hidden] {
  display: none;
}

/* --- status chip: idle / preview / result / error ------------------------- */

.chip--status {
  gap: 0.4rem;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.045em;
}

.chip--status::before {
  content: "";
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.chip--status[data-state="idle"] {
  border-color: var(--line);
  background: transparent;
  color: var(--bone-faint);
}

.chip--status[data-state="preview"] {
  border-style: dashed;
  border-color: var(--accent-line);
  background: transparent;
  color: var(--accent);
}

.chip--status[data-state="done"] {
  border-color: var(--accent-line);
  background: var(--accent-soft);
  color: var(--accent);
}

.chip--status[data-state="error"] {
  border-color: rgba(229, 144, 127, 0.45);
  background: rgba(229, 144, 127, 0.12);
  color: #e5907f;
}

.chip--status[data-soft="true"] {
  border-style: dashed;
  opacity: 0.85;
}

.chip--status[data-state="preview"]::before {
  animation: status-pulse 1.6s var(--ease) infinite;
}

@keyframes status-pulse {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.25; }
}

/* --- angle-unit toggle (a real button, in the readout meta row) ----------- */

.chip--toggle {
  appearance: none;
  cursor: pointer;
  font-family: var(--serif);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.08em;
}

.chip--toggle::after {
  content: "\21c4"; /* ⇄ — this control swaps between two units */
  font-size: 0.85em;
  opacity: 0.7;
}

.chip--toggle:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--ink);
}

.chip--toggle[data-angle="rad"] {
  border-style: dashed;
}

/* --- results sparkline ---------------------------------------------------- */

.spark {
  margin: 0 0 0 auto;
  padding: 0;
  display: flex;
  align-items: center;
  color: var(--accent);
  transition: color 0.28s var(--ease);
}

.spark__svg {
  display: block;
  width: 7.5rem;
  height: 1.9rem;
  overflow: visible;
}

.spark__axis {
  stroke: var(--line);
  stroke-width: 1;
  stroke-dasharray: 2 4;
}

.spark__line {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linejoin: round;
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
}

.spark__dot {
  fill: currentColor;
  stroke: var(--panel-raised);
  stroke-width: 1;
}

.spark[data-state="idle"] {
  color: var(--bone-faint);
}

.spark[data-state="preview"] {
  color: var(--accent);
}

.spark[data-state="error"] {
  color: #e5907f;
}

.spark[data-state="error"] .spark__line {
  stroke-dasharray: 3 3;
}

/* --- history: every entry is a real button -------------------------------- */

.history__row {
  display: block;
}

.history__entry {
  appearance: none;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 0.75rem;
  width: 100%;
  margin: 0;
  padding: 0.55rem 0.15rem;
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background-color 0.13s var(--ease), color 0.13s var(--ease);
}

.history__row:first-child .history__entry {
  border-top: 0;
}

.history__entry:hover {
  background: var(--accent-soft);
}

.history__entry:hover .history__expr {
  color: var(--bone);
}

.history__entry:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

/* --- mode-scoped: the scientific plate is the live instrument ------------- */

body[data-mode="scientific"] .calc {
  border-color: var(--accent-line);
}

body[data-mode="scientific"] .calc .readout {
  box-shadow: inset 0 0 0 1px var(--accent-line);
}

/* In graph mode the same panel stays usable but drops out of the accent so the
   amber plot is unmistakably the active surface. */
body[data-mode="graph"] .calc {
  border-color: var(--line);
}

body[data-mode="graph"] .calc .readout {
  box-shadow: none;
}

body[data-mode="graph"] .calc .panel__title {
  color: var(--bone-dim);
}

body[data-mode="graph"] .calc .key--op,
body[data-mode="graph"] .calc .key--equals {
  color: var(--bone-dim);
  background: var(--panel-raised);
  border-color: var(--line);
}

body[data-mode="graph"] .calc .key--equals:hover {
  filter: none;
  background: #17211f;
  border-color: var(--line-strong);
  color: var(--bone);
}

/* --- responsive trim for the new readout furniture ------------------------ */

@media (max-width: 560px) {
  .spark__svg { width: 5rem; height: 1.5rem; }
  .readout__note { font-size: 0.75rem; }
}

@media (max-width: 400px) {
  .spark { display: none; }
}
