/*!
 * Vernier — static/js/graph.js
 * ---------------------------------------------------------------------------
 * Graphing panel: a hand-written Canvas 2D plot for up to four expressions.
 *
 *   · smart grid + labelled axes (zero lines drawn brighter than the grid)
 *   · one colour + dash pattern per series, mirrored in the labelled legend
 *   · adaptive sampling through CalcEngine.compile / CalcEngine.sample;
 *     null samples break the polyline instead of connecting across a gap
 *   · automatic y-fit (robust, outlier-resistant) plus manual zoom and pan
 *   · drag to pan with mouse, pen or finger; explicit + / − / Fit / Reset
 *     buttons and arrow-key panning for keyboard users
 *   · hover (and focus) readout of the coordinates nearest the pointer
 *   · device-pixel-ratio aware backing store; redraws on resize
 *   · every repaint is throttled through requestAnimationFrame
 *   · view transitions are skipped when prefers-reduced-motion is set
 *
 * No libraries, no CDN, no eval/new Function. All maths (parsing, evaluation,
 * sampling, number formatting) is delegated to window.CalcEngine. Angle unit
 * and `ans` are read from the shared window.Vernier state published by
 * static/js/scientific.js, so both modes compute in the same unit.
 * ---------------------------------------------------------------------------
 */
(function (global) {
  "use strict";

  var doc = global.document;
  var Engine = global.CalcEngine;

  if (!doc || !Engine) {
    if (global.console && global.console.warn) {
      global.console.warn(
        "Vernier: static/js/graph.js needs window.CalcEngine from static/js/engine.js. Plot left inert."
      );
    }
    return;
  }

  /* ------------------------------------------------------------------ *
   * Constants
   * ------------------------------------------------------------------ */

  var MAX_SERIES = 4;
  var SERIES_LABELS = ["A", "B", "C", "D"];
  var SERIES_NAMES = ["Amber", "Ice", "Mint", "Rose"];
  var SERIES_DASH_CSS = ["solid", "dashed", "dotted", "double"];

  // Colours chosen for >= 4.5:1 contrast on the plot ground (#0b1211) and kept
  // distinct in hue *and* lightness so they survive most colour-vision types.
  // Every series also has its own dash pattern, so the line style carries the
  // same information as the colour.
  var PALETTE = [
    { color: "#f2b457", dash: [] },              // amber — the graph accent
    { color: "#8ec9f0", dash: [8, 4] },          // ice
    { color: "#a9dea6", dash: [2, 3] },          // mint
    { color: "#f2a1b6", dash: [10, 4, 2, 4] }    // rose
  ];

  var PLOT_BG = "#0b1211";
  var GRID_LINE = "rgba(242, 180, 87, 0.10)";
  var AXIS_LINE = "rgba(240, 234, 221, 0.34)";
  var LABEL_INK = "rgba(240, 234, 221, 0.58)";
  var LABEL_INK_STRONG = "rgba(240, 234, 221, 0.82)";
  var CROSSHAIR = "rgba(240, 234, 221, 0.28)";

  var MONO =
    '11px ui-monospace, "SF Mono", SFMono-Regular, "Cascadia Mono", "DejaVu Sans Mono", Menlo, Consolas, monospace';
  var MONO_SMALL =
    '10px ui-monospace, "SF Mono", SFMono-Regular, "Cascadia Mono", "DejaVu Sans Mono", Menlo, Consolas, monospace';

  var DEFAULT_HALF_X = 10;
  var DEFAULT_HALF_Y = 6;
  var WHEEL = 1.55;             // zoom step for the +/- buttons
  var TWEEN_MS = 240;           // view transition duration (skipped on reduced motion)
  var SAMPLE_PER_PX = 1.5;      // base samples per CSS pixel of plot width
  var MIN_SAMPLES = 320;
  var MAX_SAMPLES = 1600;
  var MAX_REFINE_DEPTH = 4;     // adaptive subdivisions per base segment
  var MAX_POINTS = 14000;       // per-series safety valve
  var BREAK_SCREENS = 2.5;      // asymptote break: jump > 2.5 plot heights + sign flip
  var MIN_SPAN = 1e-6;
  var MAX_SPAN = 1e12;
  var FIT_SAMPLES = 400;        // cheap pass used by Fit / Reset transitions

  var reduceQuery =
    global.matchMedia && global.matchMedia("(prefers-reduced-motion: reduce)");

  /* ------------------------------------------------------------------ *
   * State
   * ------------------------------------------------------------------ */

  var state = {
    series: [], // one record per input, index-aligned with PALETTE
    view: { xMin: -DEFAULT_HALF_X, xMax: DEFAULT_HALF_X, yMin: -DEFAULT_HALF_Y, yMax: DEFAULT_HALF_Y, autoY: true },
    hover: null, // { px, py, x, y, point: { index, x, y, distance } }
    drag: null,
    tween: null
  };

  var scope = { ans: 0 }; // stable object: engine keeps a live reference
  var dirty = true;       // inputs / view / angle changed -> recompile + resample
  var frame = null;
  var context = null;
  var el = {};
  var lastChrome = { boundX: "", boundY: "", aria: "" };

