  }

  function now() {
    return new Date().getTime();
  }

  function requestFrame(fn) {
    if (global.requestAnimationFrame) return global.requestAnimationFrame(fn);
    return global.setTimeout(fn, 16);
  }

  function format(value, precision) {
    try {
      return Engine.format(value, { precision: precision || 4 });
    } catch (error) {
      return String(value);
    }
  }

  function announce(text) {
    if (!el.announcer) return;
    el.announcer.textContent = text;
  }

  function displayExpr(source) {
    var text = String(source == null ? "" : source);
    return text
      .replace(/\*/g, "\u00d7")
      .replace(/\//g, "\u00f7")
      .replace(/(-)/g, "\u2212");
  }

  function currentAngle() {
    var app = global.Vernier;
    if (app && typeof app.getAngleMode === "function") {
      var mode = app.getAngleMode();
      if (mode) return mode;
    }
    return Engine.getAngleMode ? Engine.getAngleMode() : "DEG";
  }

  function refreshScope() {
    var app = global.Vernier;
    if (app && typeof app.getScope === "function") {
      var live = app.getScope();
      if (live && typeof live.ans === "number") scope.ans = live.ans;
    }
  }

  function compileOptions() {
    return { variable: "x", angleMode: currentAngle(), scope: scope };
  }

  function prefersReducedMotion() {
    return !!(reduceQuery && reduceQuery.matches);
  }

  function errorMessage(error) {
    if (error && error.message) return error.message;
    return "That expression could not be read.";
  }

  /* ------------------------------------------------------------------ *
   * View geometry
   * ------------------------------------------------------------------ */

  function sanitizeView(input) {
    var view = copyView(input);
    if (!isFinite(view.xMin) || !isFinite(view.xMax)) {
      view.xMin = -DEFAULT_HALF_X;
      view.xMax = DEFAULT_HALF_X;
    }
    if (!isFinite(view.yMin) || !isFinite(view.yMax)) {
      view.yMin = -DEFAULT_HALF_Y;
      view.yMax = DEFAULT_HALF_Y;
    }
    if (view.xMin > view.xMax) {
      var swapX = view.xMin;
      view.xMin = view.xMax;
      view.xMax = swapX;
    }
    if (view.yMin > view.yMax) {
      var swapY = view.yMin;
      view.yMin = view.yMax;
      view.yMax = swapY;
    }
    view.xMin = clampSpan(view.xMin, view.xMax, "xMin", "xMax");
    view.yMin = clampSpan(view.yMin, view.yMax, "yMin", "yMax");
    return view;
  }

  // Keep a span inside [MIN_SPAN, MAX_SPAN] by pushing the two bounds apart or
  // pulling them together around their midpoint. `view` is not mutated; the
  // clamped pair is written back onto the passed object by the caller.
  function clampSpan(lo, hi, loKey, hiKey) {
    var span = hi - lo;
    var mid = (lo + hi) / 2;
    if (span < MIN_SPAN) {
      span = MIN_SPAN;
      return loKey === "xMin" ? mid - span / 2 : mid - span / 2;
    }
    if (span > MAX_SPAN) {
      span = MAX_SPAN;
    }
    return loKey === "xMin" ? mid - span / 2 : loKey === "yMin" ? mid - span / 2 : hi;
  }

  // clampSpan above returns only the low bound; this pair-form keeps both in
  // step without mutating the caller's object.
  function clampPair(view, loKey, hiKey) {
    var lo = view[loKey];
    var hi = view[hiKey];
    var span = hi - lo;
    var mid = (lo + hi) / 2;
    if (!(span > 0)) span = 1;
    if (span < MIN_SPAN) span = MIN_SPAN;
    if (span > MAX_SPAN) span = MAX_SPAN;
    view[loKey] = mid - span / 2;
    view[hiKey] = mid + span / 2;
  }

  function assignView(input) {
    var next = sanitizeView(input);
    clampPair(next, "xMin", "xMax");
    clampPair(next, "yMin", "yMax");
