    dirty = true;
  }

  function unitPerPx(m) {
    return {
      x: (state.view.xMax - state.view.xMin) / Math.max(1, m.right - m.left),
      y: (state.view.yMax - state.view.yMin) / Math.max(1, m.bottom - m.top)
    };
  }

  function toScreenX(m, x) {
    return m.left + ((x - state.view.xMin) / (state.view.xMax - state.view.xMin)) * (m.right - m.left);
  }

  function toScreenY(m, y) {
    return m.bottom - ((y - state.view.yMin) / (state.view.yMax - state.view.yMin)) * (m.bottom - m.top);
  }

  function fromScreenX(m, px) {
    return state.view.xMin + ((px - m.left) / Math.max(1, m.right - m.left)) * (state.view.xMax - state.view.xMin);
  }

  function fromScreenY(m, py) {
    return state.view.yMin + ((m.bottom - py) / Math.max(1, m.bottom - m.top)) * (state.view.yMax - state.view.yMin);
  }

  /* ------------------------------------------------------------------ *
   * Robust y-fit
   * ------------------------------------------------------------------ */

  function numericSort(a, b) {
    return a - b;
  }

  function quantile(sorted, q) {
    if (!sorted.length) return 0;
    if (sorted.length === 1) return sorted[0];
    var pos = (sorted.length - 1) * q;
    var base = Math.floor(pos);
    var rest = pos - base;
    if (base + 1 < sorted.length) {
      return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
    }
    return sorted[base];
  }

  /**
   * Turn a bag of y values into a friendly window. The median absolute
   * deviation fences off asymptote tails (tan, 1/x) so one runaway sample
   * cannot squash the interesting part of the curve flat.
   */
  function robustRange(values) {
    var clean = [];
    var i;
    for (i = 0; i < values.length; i++) {
      if (typeof values[i] === "number" && isFinite(values[i])) clean.push(values[i]);
    }
    if (clean.length < 2) {
      return { yMin: -DEFAULT_HALF_Y, yMax: DEFAULT_HALF_Y };
    }
    clean.sort(numericSort);
    var median = quantile(clean, 0.5);
    var deviations = [];
    for (i = 0; i < clean.length; i++) deviations.push(Math.abs(clean[i] - median));
    deviations.sort(numericSort);
    var mad = quantile(deviations, 0.5);
    var lo = clean[0];
    var hi = clean[clean.length - 1];
    if (mad > 0) {
      var fence = 6 * mad;
      lo = Math.max(lo, median - fence);
      hi = Math.min(hi, median + fence);
    }
    if (!(hi > lo)) {
      var mid = (lo + hi) / 2;
      lo = mid - 1;
      hi = mid + 1;
    }
    // Pull a baseline in when the curve sits just above/below zero, so e^x or
    // x^2 keep their floor in frame instead of starting halfway up.
    var spread = hi - lo;
    if (lo > 0 && lo <= spread * 0.35) lo = 0;
    if (hi < 0 && -hi <= spread * 0.35) hi = 0;
    spread = hi - lo;
    var pad = spread * 0.08;
    return { yMin: lo - pad, yMax: hi + pad };
  }

  function collectYValues(view) {
    var values = [];
    var i;
    var j;
    var series = state.series;
    for (i = 0; i < series.length; i++) {
      var pts = series[i].points;
      if (!pts || !pts.length) continue;
      for (j = 0; j < pts.length; j++) {
        if (pts[j][1] !== null && isFinite(pts[j][1])) values.push(pts[j][1]);
      }
    }
    if (!values.length && !view) return values;
    return values;
  }

  /* ------------------------------------------------------------------ *
   * Sampling
   * ------------------------------------------------------------------ */

  function compileSeries(record) {
    record.compiled = null;
    record.error = null;
    if (!record.expression) return;
    try {
      record.compiled = Engine.compile(record.expression, compileOptions());
    } catch (error) {
      record.error = errorMessage(error);
    }
  }

  function compileAll() {
    var i;
    for (i = 0; i < state.series.length; i++) compileSeries(state.series[i]);
  }

  function adaptivePoints(curve, base, unitsPerPxY, plotH) {
    var out = [];
    if (!base || !base.length) return out;
    out.push(base[0]);
    var i;
    for (i = 1; i < base.length; i++) {
      refineSegment(curve, base[i - 1], base[i], 0, out, unitsPerPxY, plotH);
      out.push(base[i]);
      if (out.length > MAX_POINTS) break;
    }
    return out;
  }

  function refineSegment(curve, a, b, depth, out, unitsPerPxY, plotH) {
    if (depth >= MAX_REFINE_DEPTH || out.length > MAX_POINTS) return;
    if (a[1] === null || b[1] === null) return; // the gap already breaks the line
    var midX = (a[0] + b[0]) / 2;
    if (midX === a[0] || midX === b[0]) return;
    var raw;
    try {
      raw = curve(midX);
    } catch (error) {
      raw = NaN;
    }
    var midY = typeof raw === "number" && isFinite(raw) ? raw : null;
    var refine = false;

    if (midY === null) {
      refine = true; // a singularity hidden between two finite samples
    } else {
      var chord = (a[1] + b[1]) / 2;
      var errorPx = Math.abs(midY - chord) / unitsPerPxY;
      var jumpPx = Math.abs(b[1] - a[1]) / unitsPerPxY;
      if (errorPx > 0.4) refine = true;
      // A sign flip over a huge jump is an asymptote: subdivide to find it.
      if (jumpPx > plotH * BREAK_SCREENS && signOf(a[1]) !== signOf(b[1])) refine = true;
    }

    if (!refine) return;
    refineSegment(curve, a, [midX, midY], depth + 1, out, unitsPerPxY, plotH);
    out.push([midX, midY]);
    refineSegment(curve, [midX, midY], b, depth + 1, out, unitsPerPxY, plotH);
  }

  function summarize(record) {
    var pts = record.points;
    var finite = 0;
    var breaks = 0;
    var inNullRun = false;
    var yMin = Infinity;
    var yMax = -Infinity;
    var i;
    record.finiteCount = 0;
    record.breakCount = 0;
    record.yMin = NaN;
    record.yMax = NaN;
    for (i = 0; i < pts.length; i++) {
      var y = pts[i][1];
      if (y === null || !isFinite(y)) {
        if (!inNullRun) {
          inNullRun = true;
          breaks++;
        }
      } else {
        inNullRun = false;
        finite++;
        if (y < yMin) yMin = y;
        if (y > yMax) yMax = y;
      }
    }
    record.finiteCount = finite;
    record.breakCount = Math.max(0, breaks - 1);
    if (finite) {
      record.yMin = yMin;
      record.yMax = yMax;
    }
  }

  function ensureSamples() {
    var m = metrics();
    if (!m) return;
    refreshScope();
    var count = clamp(Math.round((m.right - m.left) * SAMPLE_PER_PX), MIN_SAMPLES, MAX_SAMPLES);
    var units = unitPerPx(m);
    var plotH = m.bottom - m.top;
    var opts = compileOptions();
    var i;

    for (i = 0; i < state.series.length; i++) {
      var record = state.series[i];
      record.points = [];
      record.active = !!record.expression;
      if (!record.expression) {
        summarize(record);
        continue;
      }
      if (record.error) {
        compileSeries(record); // retry: the angle unit or ans may have changed
      }
      if (!record.compiled || record.error) {
        summarize(record);
        continue;
      }
      var base;
      try {
        base = Engine.sample(record.compiled, state.view.xMin, state.view.xMax, count, opts);
      } catch (error) {
        record.error = errorMessage(error);
        record.compiled = null;
        summarize(record);
        continue;
      }
      record.points = adaptivePoints(record.compiled, base, units.y, plotH);
      summarize(record);
    }
  }

  // Cheap sampling pass used to work out where an animated view should land.
  function fitForWindow(xMin, xMax) {
    var values = [];
    var opts = compileOptions();
    var i;
    refreshScope();
    for (i = 0; i < state.series.length; i++) {
      var record = state.series[i];
      if (!record.compiled || !record.expression) continue;
      var pts;
      try {
        pts = Engine.sample(record.compiled, xMin, xMax, FIT_SAMPLES, opts);
      } catch (error) {
        continue;
      }
      var j;
      for (j = 0; j < pts.length; j++) {
        if (pts[j][1] !== null && isFinite(pts[j][1])) values.push(pts[j][1]);
      }
    }
    return robustRange(values);
  }

  /* ------------------------------------------------------------------ *
   * Smart ticks
   * ------------------------------------------------------------------ */

  var NICE_STEPS = [1, 2, 2.5, 5, 10];

  function niceStep(span, target) {
    var raw = span / Math.max(1, target);
    if (!(raw > 0) || !isFinite(raw)) return 1;
    var power = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10));
    var normalised = raw / power;
    var i;
    for (i = 0; i < NICE_STEPS.length; i++) {
      if (normalised <= NICE_STEPS[i] * 1.0001) return NICE_STEPS[i] * power;
    }
    return 10 * power;
  }

  function decimalsForStep(step) {
    var d = 0;
    var scaled = Math.abs(step);
    while (d < 8 && Math.abs(scaled - Math.round(scaled)) > 1e-9) {
      scaled *= 10;
      d++;
    }
    return d;
  }

  function tickText(value, step) {
    var abs = Math.abs(value);
    if (abs !== 0 && (abs >= 1e7 || abs < 1e-4)) {
      return value
        .toExponential(1)
        .replace(/\.0e/, "e")
        .replace(/e\+/, "e");
    }
    var text = value.toFixed(decimalsForStep(step));
    if (/^-0(\.0*)?$/.test(text)) text = text.slice(1);
    if (/^-0\.0+$/.test(text)) text = "0";
    return text;
  }

  function tickValues(min, max, step) {
    var values = [];
    var first = Math.ceil(min / step) * step;
    var guard = 0;
    var value = first;
    while (value <= max + step * 1e-6 && guard < 400) {
      // Snap values that are a hair away from a clean multiple.
      values.push(Math.abs(value) < step * 1e-9 ? 0 : value);
      guard++;
      value = first + step * guard;
    }
    return values;
  }

  /* ------------------------------------------------------------------ *
   * Canvas sizing
   * ------------------------------------------------------------------ */

  function metrics() {
    if (!el.plot || !el.canvas) return null;
    var w = el.plot.clientWidth;
    var h = el.plot.clientHeight;
    if (!w || !h) return null;
    var ratio = global.devicePixelRatio || 1;
    if (!(ratio > 0)) ratio = 1;
    var bw = Math.round(w * ratio);
    var bh = Math.round(h * ratio);
    if (el.canvas.width !== bw || el.canvas.height !== bh) {
      el.canvas.width = bw;
      el.canvas.height = bh;
      context = null;
    }
    if (!context) context = el.canvas.getContext("2d");
    if (!context) return null;
    context.setTransform(ratio, 0, 0, ratio, 0, 0);

    var padLeft = w < 380 ? 38 : 48;
    var padBottom = h < 230 ? 24 : 30;
    var left = padLeft;
    var right = Math.max(padLeft + 20, w - 12);
    var top = 12;
    var bottom = Math.max(top + 20, h - padBottom);
    return {
      w: w,
      h: h,
      left: left,
      right: right,
      top: top,
      bottom: bottom,
      plotW: right - left,
      plotH: bottom - top,
      ratio: ratio
    };
  }

  /* ------------------------------------------------------------------ *
   * Painting
   * ------------------------------------------------------------------ */

  function paint(m) {
    var ctx = context;
    if (!ctx) return;
    ctx.setTransform(m.ratio, 0, 0, m.ratio, 0, 0);
    ctx.clearRect(0, 0, m.w, m.h);
    ctx.fillStyle = PLOT_BG;
    ctx.fillRect(0, 0, m.w, m.h);

    var xt = niceStep(state.view.xMax - state.view.xMin, Math.max(2, Math.floor(m.plotW / 88)));
    var yt = niceStep(state.view.yMax - state.view.yMin, Math.max(2, Math.floor(m.plotH / 54)));

    paintGrid(ctx, m, xt, yt);
    paintAxes(ctx, m, xt, yt);
    paintCurves(ctx, m);
    paintHover(ctx, m);
  }

  function paintGrid(ctx, m, xt, yt) {
    var xs = tickValues(state.view.xMin, state.view.xMax, xt);
    var ys = tickValues(state.view.yMin, state.view.yMax, yt);
    var i;

    ctx.save();
    ctx.beginPath();
    ctx.rect(m.left, m.top, m.plotW, m.plotH);
    ctx.clip();
    ctx.strokeStyle = GRID_LINE;
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (i = 0; i < xs.length; i++) {
      var sx = Math.round(toScreenX(m, xs[i])) + 0.5;
      ctx.moveTo(sx, m.top);
      ctx.lineTo(sx, m.bottom);
    }
    for (i = 0; i < ys.length; i++) {
      var sy = Math.round(toScreenY(m, ys[i])) + 0.5;
      ctx.moveTo(m.left, sy);
      ctx.lineTo(m.right, sy);
    }
    ctx.stroke();
    ctx.restore();
  }

  function paintAxes(ctx, m, xt, yt) {
    var view = state.view;
    var zeroX = toScreenX(m, 0);
    var zeroY = toScreenY(m, 0);
    var xAxisVisible = view.yMin <= 0 && view.yMax >= 0;
    var yAxisVisible = view.xMin <= 0 && view.xMax >= 0;
    var xs = tickValues(view.xMin, view.xMax, xt);
    var ys = tickValues(view.yMin, view.yMax, yt);
    var i;

    ctx.save();
    ctx.beginPath();
    ctx.rect(m.left - 0.5, m.top - 0.5, m.plotW + 1, m.plotH + 1);
    ctx.clip();

    // zero lines sit brighter than the grid so the axes read as axes
    ctx.strokeStyle = AXIS_LINE;
    ctx.lineWidth = 1.25;
    ctx.beginPath();
    if (xAxisVisible) {
      var ay = Math.round(zeroY) + 0.5;
      ctx.moveTo(m.left, ay);
      ctx.lineTo(m.right, ay);
    }
    if (yAxisVisible) {
      var ax = Math.round(zeroX) + 0.5;
      ctx.moveTo(ax, m.top);
      ctx.lineTo(ax, m.bottom);
    }
    ctx.stroke();
    ctx.restore();

    // tick text under the plot / beside it, never inside the curves
    ctx.save();
    ctx.font = MONO_SMALL;
    ctx.fillStyle = LABEL_INK;

    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    for (i = 0; i < xs.length; i++) {
      var px = toScreenX(m, xs[i]);
      if (px < m.left - 2 || px > m.right + 2) continue;
      ctx.strokeStyle = LABEL_INK;
      ctx.beginPath();
      ctx.moveTo(Math.round(px) + 0.5, m.bottom);
      ctx.lineTo(Math.round(px) + 0.5, m.bottom + 3);
      ctx.stroke();
      ctx.fillText(tickText(xs[i], xt), px, m.bottom + 11);
    }

    ctx.textAlign = "right";
    for (i = 0; i < ys.length; i++) {
      var py = toScreenY(m, ys[i]);
      if (py < m.top - 2 || py > m.bottom + 2) continue;
      ctx.beginPath();
      ctx.moveTo(m.left - 3, Math.round(py) + 0.5);
      ctx.lineTo(m.left, Math.round(py) + 0.5);
      ctx.stroke();
      ctx.fillText(tickText(ys[i], yt), m.left - 6, py);
    }

    // axis names: x along the horizontal axis, y at the top of the vertical one
    ctx.fillStyle = LABEL_INK_STRONG;
    ctx.font = MONO;
    if (xAxisVisible) {
      var nameY = clamp(zeroY - 8, m.top + 8, m.bottom - 8);
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      ctx.fillText("x", m.right - 3, nameY);
    }
    if (yAxisVisible) {
      var nameX = clamp(zeroX + 7, m.left + 6, m.right - 6);
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      ctx.fillText("y", nameX, m.top + 3);
    }
    ctx.restore();
  }

  function curvePath(ctx, m, points) {
    var units = unitPerPx(m);
    var breakPx = m.plotH * BREAK_SCREENS;
    var drawing = false;
    var prevY = 0;
    var prevSy = 0;
    var i;

    ctx.beginPath();
    for (i = 0; i < points.length; i++) {
      var point = points[i];
      var y = point[1];
      if (y === null || !isFinite(y)) {
        drawing = false;
        continue;
      }
      var sx = toScreenX(m, point[0]);
      var sy = toScreenY(m, y);
      // Clamp absurd coordinates; clipping hides them anyway.
      if (sy < -10000) sy = -10000;
      if (sy > 10000) sy = 10000;

      if (!drawing) {
        ctx.moveTo(sx, sy);
        drawing = true;
      } else {
        // Asymptote: huge screen jump *and* a sign flip means the two samples
        // are on opposite branches. Break instead of drawing a vertical bar.
        var jumped = Math.abs(sy - prevSy) > breakPx || Math.abs(y - prevY) / units.y > breakPx;
        if (jumped && signOf(y) !== signOf(prevY)) {
          ctx.moveTo(sx, sy);
        } else {
          ctx.lineTo(sx, sy);
        }
      }
      prevY = y;
      prevSy = sy;
    }
  }

  function paintCurves(ctx, m) {
    var i;
    ctx.save();
    ctx.beginPath();
    ctx.rect(m.left, m.top, m.plotW, m.plotH);
    ctx.clip();

    // Draw inactive/hovered last so the highlighted curve stays on top.
    for (i = 0; i < state.series.length; i++) {
      var record = state.series[i];
      if (!record.points || !record.points.length || !record.finiteCount) continue;
      var palette = PALETTE[i];
      ctx.strokeStyle = palette.color;
      ctx.lineWidth = 2;
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      if (ctx.setLineDash) ctx.setLineDash(palette.dash);
      curvePath(ctx, m, record.points);
      ctx.stroke();
    }

    if (ctx.setLineDash) ctx.setLineDash([]);
    ctx.restore();
  }

  function paintHover(ctx, m) {
    var hover = state.hover;
    if (!hover) return;
    ctx.save();
    ctx.beginPath();
    ctx.rect(m.left, m.top, m.plotW, m.plotH);
    ctx.clip();

    ctx.strokeStyle = CROSSHAIR;
    ctx.lineWidth = 1;
    if (ctx.setLineDash) ctx.setLineDash([3, 4]);
    ctx.beginPath();
    ctx.moveTo(Math.round(hover.px) + 0.5, m.top);
    ctx.lineTo(Math.round(hover.px) + 0.5, m.bottom);
    ctx.moveTo(m.left, Math.round(hover.py) + 0.5);
    ctx.lineTo(m.right, Math.round(hover.py) + 0.5);
    ctx.stroke();
    if (ctx.setLineDash) ctx.setLineDash([]);

    // A marker on every curve at the hovered x, ringed so it reads on the line.
    var i;
    for (i = 0; i < hover.markers.length; i++) {
      var marker = hover.markers[i];
      var px = toScreenX(m, marker.x);
      var py = toScreenY(m, marker.y);
      if (py < m.top - 8 || py > m.bottom + 8) continue;
      ctx.beginPath();
      ctx.arc(px, py, marker.primary ? 4 : 3, 0, Math.PI * 2);
      ctx.fillStyle = PALETTE[marker.index].color;
      ctx.fill();
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = PLOT_BG;
      ctx.stroke();
    }
    ctx.restore();
  }

  /* ------------------------------------------------------------------ *
   * Hover readout
   * ------------------------------------------------------------------ */

  function nearestPoint(points, x, tolerance) {
    if (!points || !points.length) return null;
    var lo = 0;
    var hi = points.length - 1;
    while (hi - lo > 1) {
      var mid = (lo + hi) >> 1;
      if (points[mid][0] < x) lo = mid;
      else hi = mid;
    }
    var best = null;
    var candidates = [lo, hi, lo - 1, hi + 1];
    var i;
    for (i = 0; i < candidates.length; i++) {
      var index = candidates[i];
      if (index < 0 || index >= points.length) continue;
      var point = points[index];
      if (point[1] === null || !isFinite(point[1])) continue;
      var distance = Math.abs(point[0] - x);
      if (distance <= tolerance && (!best || distance < best.distance)) {
        best = { x: point[0], y: point[1], distance: distance };
      }
    }
    return best;
  }

  function setHover(px, py) {
    var m = metrics();
    if (!m) {
      state.hover = null;
      return;
    }
    if (px < m.left || px > m.right || py < m.top || py > m.bottom) {
      state.hover = null;
      updateHoverReadout(m);
      return;
    }
    var x = fromScreenX(m, px);
    var tolerance = ((state.view.xMax - state.view.xMin) / Math.max(1, m.plotW)) * 4;
    var markers = [];
    var nearest = null;
    var nearestIndex = -1;
    var i;

    for (i = 0; i < state.series.length; i++) {
      var record = state.series[i];
      if (!record.points || !record.points.length || !record.finiteCount) continue;
      var hit = nearestPoint(record.points, x, tolerance);
      if (!hit) continue;
      markers.push({ index: i, x: hit.x, y: hit.y, screenY: toScreenY(m, hit.y) });
      var screenDistance = Math.abs(toScreenY(m, hit.y) - py);
      if (!nearest || screenDistance < nearest.distance) {
        nearest = { index: i, x: hit.x, y: hit.y, distance: screenDistance };
        nearestIndex = markers.length - 1;
      }
    }
    if (nearestIndex >= 0) markers[nearestIndex].primary = true;

    state.hover = {
      px: px,
      py: py,
      x: x,
      y: fromScreenY(m, py),
      markers: markers,
      point: nearest
    };
    updateHoverReadout(m);
  }

  function updateHoverReadout(m) {
    if (!el.hover) return;
    var hover = state.hover;
    if (!hover) {
      el.hover.setAttribute("hidden", "hidden");
      return;
    }
    var parts = ["x " + format(hover.x, 4)];
    if (hover.point) {
      parts.push(SERIES_LABELS[hover.point.index] + "  y " + format(hover.point.y, 4));
    } else {
      parts.push("y " + format(hover.y, 4));
    }
    el.hover.textContent = parts.join("   ");
    el.hover.removeAttribute("hidden");

    // Keep the pill inside the plot without covering the cursor.
    var rect = el.hover.getBoundingClientRect();
    var width = rect.width || 140;
    var height = rect.height || 24;
    var left = hover.px + 14;
    if (left + width > m.w - 4) left = hover.px - 14 - width;
    left = clamp(left, 4, Math.max(4, m.w - width - 4));
    var top = hover.py - height - 10;
    if (top < 4) top = hover.py + 14;
    top = clamp(top, 4, Math.max(4, m.h - height - 4));
    el.hover.style.left = Math.round(left) + "px";
    el.hover.style.top = Math.round(top) + "px";
  }

  /* ------------------------------------------------------------------ *
   * DOM chrome: per-series state, legend, bounds, accessible label
   * ------------------------------------------------------------------ */

  function describeSeries(record, index) {
    if (!record.expression) {
      return { state: "empty", tone: "quiet", text: "", error: null };
    }
    if (record.error) {
      return { state: "error", tone: "error", text: record.error, error: record.error };
    }
    if (!record.finiteCount) {
      return {
        state: "empty",
        tone: "quiet",
        text: "No points in this window. Zoom out or try another range.",
        error: null
      };
    }
    var text = "Plotted · y " + format(record.yMin, 3) + " to " + format(record.yMax, 3);
    if (record.breakCount > 0) {
      text += " · " + record.breakCount + (record.breakCount === 1 ? " break" : " breaks");
    }
    return { state: "ok", tone: "quiet", text: text, error: null };
  }

  function renderSeriesChrome() {
    var i;
