cd static && cat >> css/style.css <<'CSS'

/* --------------------------------------------------------------------------
   Graph plate: canvas furniture, per-series state, legend
   (task 4 — appended, no earlier rule retuned)
   -------------------------------------------------------------------------- */

/* The canvas owns the grid, so the plot ground is flat and the pointer
   gestures belong to the plot (no page scroll while panning). */
.plot {
  touch-action: none;
  cursor: crosshair;
  background: #0b1211;
}

#graph-canvas {
  touch-action: none;
  cursor: crosshair;
}

#graph-canvas.is-dragging { cursor: grabbing; }

#graph-canvas:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.plot__empty[hidden] { display: none; }
.plot__empty { pointer-events: none; }

/* --- floating view controls ---------------------------------------------- */

.plot__tools {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  z-index: 2;
  display: flex;
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: rgba(10, 15, 15, 0.82);
  backdrop-filter: blur(2px);
}

.plot__tool {
  appearance: none;
  min-width: 1.75rem;
  height: 1.6rem;
  padding: 0 0.42rem;
  border: 0;
  border-radius: 1px;
  background: transparent;
  color: var(--bone-dim);
  font-family: var(--serif);
  font-size: 0.85rem;
  line-height: 1;
  cursor: pointer;
  transition: background-color 0.13s var(--ease), color 0.13s var(--ease);
}

.plot__tool:hover {
  background: var(--accent-soft);
  color: var(--accent);
}

.plot__tool--reset {
  font-size: 0.74rem;
  letter-spacing: 0.02em;
}

.plot__tool:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

/* --- hover readout -------------------------------------------------------- */

.plot__hover {
  position: absolute;
  z-index: 2;
  top: 0;
  left: 0;
  padding: 0.16rem 0.42rem;
  border: 1px solid var(--accent-line);
  border-radius: var(--radius-sm);
  background: rgba(10, 15, 15, 0.9);
  color: var(--bone);
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  font-size: 0.72rem;
  white-space: pre;
  pointer-events: none;
}

.plot__hover[hidden] { display: none; }

/* --- expression rows ------------------------------------------------------ */

.graph__field {
  border-color: var(--line);
  transition: border-color 0.15s var(--ease), background-color 0.15s var(--ease);
}

.graph__line {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-width: 0;
}

.graph__note {
  margin: 0.1rem 0 0 1.05rem;
  color: var(--bone-faint);
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  font-size: 0.7rem;
  line-height: 1.45;
}

.graph__note[data-tone="error"] { color: #e5907f; }
.graph__note[hidden] { display: none; }

.graph__field[data-state="error"] {
  border-color: rgba(229, 144, 127, 0.55);
  background: rgba(229, 144, 127, 0.05);
}

.graph__field[data-state="error"] .swatch { opacity: 0.6; }
.graph__field[data-state="empty"] .swatch { opacity: 0.45; }

.graph__actions {
  align-items: center;
  gap: 0.7rem;
  padding-top: 0.15rem;
}

.graph__hint {
  color: var(--bone-faint);
  font-size: 0.72rem;
  font-style: italic;
}

/* Swatch fallbacks: graph.js paints the real palette colours on load, these
   keep the markup legible before the script runs. */
.swatch--b { background: #8ec9f0; }
.swatch--c { background: #a9dea6; }
.swatch--d { background: #f2a1b6; }

/* --- legend --------------------------------------------------------------- */

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem 1.15rem;
  margin: 0;
  padding: 0.65rem 0 0;
  border-top: 1px solid var(--line);
  list-style: none;
}

.legend__item {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  color: var(--bone-dim);
  font-size: 0.76rem;
}

.legend__key {
  flex: none;
  width: 1.35rem;
  height: 0;
  border-top-width: 2px;
  border-top-style: solid;
  border-top-color: var(--accent);
}

.legend__tag {
  flex: none;
  font-family: var(--figures);
  font-size: 0.7rem;
  color: var(--bone-faint);
  letter-spacing: 0.04em;
}

.legend__expr {
  min-width: 0;
  overflow-wrap: anywhere;
  font-family: var(--figures);
  font-variant-numeric: tabular-nums;
  color: var(--bone);
}

.legend__state {
  color: var(--bone-faint);
  font-size: 0.68rem;
  font-style: italic;
}

.legend__item[data-state="empty"] .legend__expr { color: var(--bone-dim); }
.legend__item[data-state="empty"] .legend__key { opacity: 0.4; }

.legend__item[data-state="error"] .legend__expr {
  color: #e5907f;
  text-decoration: line-through;
  text-decoration-thickness: 1px;
}

.legend__item[data-state="error"] .legend__key { opacity: 0.35; }

@media (max-width: 560px) {
  .plot__tools { top: 0.3rem; right: 0.3rem; }
  .plot__tool { min-width: 1.5rem; height: 1.5rem; padding: 0 0.32rem; }
  .legend { gap: 0.25rem 0.8rem; }
}

@media (max-width: 400px) {
  .graph__hint { display: none; }
  .legend__state { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .plot__tool,
  .graph__field { transition: none; }
}
