/*!
 * Vernier — static/js/app.js
 * ---------------------------------------------------------------------------
 * The shell orchestrator. Loaded last, after engine.js, scientific.js and
 * graph.js, so every panel is already wired when this file boots.
 *
 * What lives here
 *   mode switch   body[data-mode] + the tabs' aria-selected/tabindex are set
 *                 together, the plate title, the mode chip and the mode band
 *                 (lamp + name + blurb + shortcut hints) follow.
 *   shared store  a small store over the state the panels share — angle unit,
 *                 last answer, history, graph expressions. Angle is mirrored
 *                 into CalcEngine.setAngleMode() by scientific.js, so graph
 *                 sampling picks it up without being told.
 *   persistence   localStorage for angle unit, history and graph expressions,
 *                 with an in-memory fallback when storage is blocked (file://,
 *                 private windows, quota) and a visible note when that happens.
 *   deep links    #scientific / #graph are read on boot and on hashchange, and
 *                 written with history.replaceState. Anything unrecognised,
 *                 or a browser that refuses replaceState, is simply ignored.
 *   shortcuts     Alt+1 / Alt+2 (also Alt+S / Alt+G) switch mode from anywhere;
 *                 Escape leaves a graph expression field and puts focus on the
 *                 plot. Panel-specific keys stay in the panels.
 *   announce      one polite live region (#announcer) shared by the whole app,
 *                 plus reportError() so a failure is never silent.
 *   self test     ?selftest or #selftest runs CalcEngine.logSelfTest().
 *
 * No dependencies, no modules, no fetch. Classic ES5 script.
 * ---------------------------------------------------------------------------
 */
(function (global) {
  "use strict";

  var doc = global.document;

  if (!doc) {
    if (global.console && global.console.warn) {
      global.console.warn("Vernier: static/js/app.js needs a DOM; nothing orchestrated.");
    }
    return;
  }

  var Engine = global.CalcEngine;
  var app = global.Vernier || (global.Vernier = {});

  /* ------------------------------------------------------------------ *
   * Constants
   * ------------------------------------------------------------------ */

  var STORAGE_PREFIX = "vernier.v1.";
  var MAX_HISTORY = 50;
  var MAX_EXPRESSION = 220;
  var MAX_RESULT = 32;
  var GRAPH_SAVE_DELAY = 400;

  var MODES = {
    scientific: {
      name: "Scientific",
      label: "Scientific mode",
      blurb:
        "Keypad with a live preview: every keystroke is evaluated as you type, " +
        "and equals files the result in the ledger.",
      keys: "Alt 1\u20132 switch \u00b7 Enter evaluates \u00b7 Esc clears"
    },
    graph: {
      name: "Graph",
      label: "Graph mode",
      blurb:
        "Four curves in x, sampled with the same angle unit and the same last " +
        "answer as the keypad. Drag to pan, + and \u2212 to zoom.",
      keys: "drag pan \u00b7 + \u2212 zoom \u00b7 F fit \u00b7 0 reset \u00b7 Alt 1\u20132 switch"
    }
  };

  var GRAPH_INPUT_IDS = [
    "graph-expression",
    "graph-expression-b",
    "graph-expression-c",
    "graph-expression-d"
  ];

  var el = {};

  /* ------------------------------------------------------------------ *
   * Small helpers
   * ------------------------------------------------------------------ */

  function byId(id) {
    return doc.getElementById(id);
  }

  function trim(text) {
    return String(text == null ? "" : text).replace(/^\s+|\s+$/g, "");
  }

  function closest(node, selector) {
    var target = node;
    while (target && target !== doc) {
      if (target.nodeType === 1) {
        if (target.matches && target.matches(selector)) return target;
        if (target.msMatchesSelector && target.msMatchesSelector(selector)) return target;
        if (target.webkitMatchesSelector && target.webkitMatchesSelector(selector)) return target;
      }
      target = target.parentNode;
    }
    return null;
  }

  function warn(message, detail) {
    if (!global.console || !global.console.warn) return;
    if (typeof detail === "undefined") global.console.warn("Vernier: " + message);
    else global.console.warn("Vernier: " + message, detail);
  }

  function normalizeMode(mode) {
    return String(mode == null ? "" : mode).toLowerCase() === "graph" ? "graph" : "scientific";
  }

  function normalizeAngle(mode) {
    return String(mode == null ? "" : mode).toUpperCase() === "RAD" ? "RAD" : "DEG";
  }

  function formatValue(value) {
    if (Engine && typeof Engine.format === "function") {
      try {
        return Engine.format(value, { precision: 12 });
      } catch (error) {
        /* fall through to String() */
      }
    }
    return String(value);
  }

  /* ------------------------------------------------------------------ *
   * Shared announcement / error channel
   * ------------------------------------------------------------------ */

  var announceTimer = null;

  /**
   * The one live region for the whole app. Clearing first makes a repeated,
   * identical sentence speak again on the next tick.
   */
  function announce(message) {
    var region = el.announcer || byId("announcer");
    if (!region || !message) return;
    region.textContent = "";
    if (announceTimer) global.clearTimeout(announceTimer);
    announceTimer = global.setTimeout(function () {
      announceTimer = null;
      region.textContent = message;
    }, 40);
  }

  /** Drop a pending announcement (used when a restore would only be noise). */
  function quietAnnouncement(delay) {
    global.setTimeout(function () {
      var region = el.announcer || byId("announcer");
      if (region) region.textContent = "";
    }, delay || 180);
  }

  /** A failure nobody else caught: log it and say it, do not swallow it. */
  function reportError(message, detail, source) {
    var text = message || "Something went wrong.";
    if (global.console && global.console.error) {
      global.console.error("Vernier [" + (source || "app") + "]: " + text, detail || "");
    }
    announce(text);
    return text;
  }

  /* ------------------------------------------------------------------ *
   * Storage — localStorage with an in-memory fallback
   * ------------------------------------------------------------------ */

  function probeStorage() {
    var storage = null;
    try {
      storage = global.localStorage;
    } catch (error) {
      storage = null; // file:// in some browsers throws on access alone
    }
    if (!storage) return null;
    try {
      var probe = STORAGE_PREFIX + "probe";
      storage.setItem(probe, "1");
      storage.removeItem(probe);
      return storage;
    } catch (error) {
      return null; // private mode / quota / blocked writes
    }
  }

  var disk = probeStorage();
  var memory = {};

  function readValue(key) {
    var raw = null;
    if (disk) {
      try {
        raw = disk.getItem(STORAGE_PREFIX + key);
      } catch (error) {
        raw = null;
      }
    } else if (Object.prototype.hasOwnProperty.call(memory, key)) {
      raw = memory[key];
    }
    if (raw == null || raw === "") return null;
    try {
      return JSON.parse(raw);
    } catch (error) {
      warn("ignoring unreadable saved value for " + key + ".");
      return null;
    }
  }

  function writeValue(key, value) {
    var raw;
    try {
      raw = JSON.stringify(value);
    } catch (error) {
      return false;
    }
    if (raw == null) return false;
    if (disk) {
      try {
        disk.setItem(STORAGE_PREFIX + key, raw);
        return true;
      } catch (error) {
        // A full quota must not break the session: keep going in memory.
      }
    }
    memory[key] = raw;
    return false;
  }

  /* ------------------------------------------------------------------ *
   * Shared state (the store)
   * ------------------------------------------------------------------ */

  var shared = {
    mode: normalizeMode(doc.body && doc.body.getAttribute("data-mode")),
    angleMode: "DEG",
    ans: 0,
    history: [],
    graph: { expressions: [] }
  };

  var watchers = {};

  function liveState() {
    var state = app.state;
    return state && typeof state === "object" ? state : null;
  }

  function currentAngle() {
    var state = liveState();
    if (state && (state.angleMode === "DEG" || state.angleMode === "RAD")) {
      return state.angleMode;
    }
    return shared.angleMode === "RAD" ? "RAD" : "DEG";
  }

  function currentAns() {
    var state = liveState();
    if (state && typeof state.ans === "number") return state.ans;
    return typeof shared.ans === "number" ? shared.ans : 0;
  }

  function currentHistory() {
    var state = liveState();
    if (state && state.history && typeof state.history.length === "number") {
      return state.history;
    }
    return shared.history;
  }

  function emit(name, value) {
    var list = watchers[name];
    if (!list || !list.length) return;
    for (var i = 0; i < list.length; i++) {
      try {
        list[i](value, shared);
      } catch (error) {
        if (global.console && global.console.error) global.console.error(error);
      }
    }
  }

  var store = {
    state: shared,
    persistent: !!disk,
    get: function (key) {
      switch (key) {
        case "mode":
          return shared.mode;
        case "angleMode":
          return currentAngle();
        case "ans":
          return currentAns();
        case "history":
          return currentHistory();
        case "graph":
          return shared.graph;
        default:
          return shared[key];
      }
    },
    set: function (key, value) {
      switch (key) {
        case "mode":
          setMode(value, { quiet: true });
          return store.get("mode");
        case "angleMode":
          setAngleMode(value);
          return store.get("angleMode");
        case "history":
          applyHistory(value);
          return store.get("history");
        case "graph":
          applyGraphExpressions(value);
          return store.get("graph");
        case "ans":
          return currentAns(); // ans belongs to the keypad; read only
        default:
          shared[key] = value;
          emit(key, value);
          return value;
      }
    },
    subscribe: function (key, handler) {
      if (typeof handler !== "function") return function () {};
      var list = watchers[key] || (watchers[key] = []);
      list.push(handler);
      return function () {
        var index = list.indexOf(handler);
        if (index >= 0) list.splice(index, 1);
      };
    }
  };

  /* ------------------------------------------------------------------ *
   * Angle unit — shared with graph sampling
   * ------------------------------------------------------------------ */

  function persistAngle(mode) {
    writeValue("angle", mode);
  }

  function setAngleMode(mode) {
    var next = normalizeAngle(mode);
    if (next === currentAngle()) {
      shared.angleMode = next;
      persistAngle(next);
      return next;
    }
    shared.angleMode = next;
    if (typeof app.setAngleMode === "function") {
      // scientific.js mirrors this into CalcEngine.setAngleMode(), repaints the
      // chip, sets body[data-angle] and emits "anglechange".
      app.setAngleMode(next);
    } else {
      if (Engine && Engine.setAngleMode) Engine.setAngleMode(next);
      if (doc.body) doc.body.setAttribute("data-angle", next.toLowerCase());
      persistAngle(next);
      emit("angleMode", next);
    }
    return next;
  }

  function restoreAngle() {
    shared.angleMode = currentAngle();
    var saved = readValue("angle");
    if (saved !== "DEG" && saved !== "RAD") {
      persistAngle(shared.angleMode); // seed storage with the current unit
      return;
    }
    if (saved === currentAngle()) {
      persistAngle(saved);
      return;
    }
    setAngleMode(saved);
    quietAnnouncement(220); // the chip already shows it; do not talk on load
  }

  /* ------------------------------------------------------------------ *
   * History — restored into the keypad's array, ledger repainted
   * ------------------------------------------------------------------ */

  function sanitizeHistory(raw) {
    var out = [];
    if (!raw || typeof raw.length !== "number") return out;
    for (var i = 0; i < raw.length && out.length < MAX_HISTORY; i++) {
      var entry = raw[i];
      if (!entry || typeof entry !== "object") continue;
      var expression =
        typeof entry.expression === "string" ? trim(entry.expression).slice(0, MAX_EXPRESSION) : "";
      if (!expression) continue;
      var value = typeof entry.value === "number" ? entry.value : parseFloat(entry.value);
      if (typeof value !== "number" || !isFinite(value)) value = NaN;
