/* ==========================================================================
   App shell — mode band, mode lamp, storage note
   Appended by the app-shell task. Nothing above this line changed; every
   colour here is a mode token, so the band re-channels with body[data-mode].
   ========================================================================== */

/* The identity strip under the masthead. Three registers: the lamp + mode name
   (what you are in), the blurb (what that mode can do), the keys (how to drive
   it). The left rule is the accent, so the band is the loudest mode signal after
   the switch itself. */
.modeband {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 0.5rem 0.9rem;
  padding: 0.15rem 0 0.15rem 0.8rem;
  border-left: 2px solid var(--accent);
  transition: border-color 0.28s var(--ease);
}

.modeband__id {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
}

/* The lamp: a filled pip with a single slow ring. Circle for scientific, square
   for graph — the shape is the cue for anyone who cannot read colour. */
.modeband__lamp {
  position: relative;
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: var(--accent);
  transition: background-color 0.28s var(--ease), border-radius 0.2s var(--ease);
}

body[data-mode="graph"] .modeband__lamp { border-radius: 1px; }

.modeband__lamp::after {
  content: "";
  position: absolute;
  inset: -4px;
  border: 1px solid var(--accent);
  border-radius: inherit;
  animation: modeband-ring 2.6s var(--ease) infinite;
}

@keyframes modeband-ring {
  0%   { transform: scale(0.55); opacity: 0.7; }
  70%,
  100% { transform: scale(1.65); opacity: 0; }
}

/* Graph mode rings faster: the same pip, a different pulse. */
body[data-mode="graph"] .modeband__lamp::after {
  animation-duration: 1.7s;
  animation-timing-function: linear;
}

.modeband__name {
  font-family: var(--serif);
  font-size: 0.95rem;
  font-variant-caps: small-caps;
  letter-spacing: 0.07em;
  line-height: 1.1;
  color: var(--accent);
  transition: color 0.28s var(--ease);
}

.modeband__blurb {
  min-width: 0;
  color: var(--bone-dim);
  font-size: 0.85rem;
  font-style: italic;
  line-height: 1.4;
}

.modeband__keys {
  color: var(--bone-faint);
  font-family: var(--figures);
  font-size: 0.7rem;
  letter-spacing: 0.02em;
  line-height: 1.5;
  text-align: right;
  white-space: nowrap;
}

/* Storage fallback note: only un-hidden by app.js when localStorage is blocked. */
.colophon__note {
  margin-top: 0.25rem;
  color: var(--accent);
  font-size: 0.74rem;
  font-style: italic;
  line-height: 1.4;
}

.colophon__note[hidden] { display: none; }

@media (max-width: 860px) {
  .modeband { grid-template-columns: auto minmax(0, 1fr); }

  .modeband__keys {
    grid-column: 1 / -1;
    text-align: left;
    white-space: normal;
  }
}

@media (max-width: 560px) {
  .modeband { padding-left: 0.6rem; gap: 0.3rem 0.7rem; }

  .modeband__blurb { font-size: 0.8rem; }

  .modeband__keys { font-size: 0.66rem; }
}

/* The ring is decoration: under reduced motion the pip simply sits there. */
@media (prefers-reduced-motion: reduce) {
  .modeband__lamp::after { animation: none; opacity: 0.5; transform: none; }
}
